{"tool": "brick.build", "input": {"code": "script({title:'Pelican on a Bicycle',palette:{},defaults:{interior:'solid'}});
const slab=(x,y,z,w,h,d,c)=>h>=3?box({at:[x,y,z],size:[w,h,d],colour:c}):floor({at:[x,y,z],size:[w,d],layers:h,colour:c});
function tube(xa,ya,xb,yb,z,d,th,c,tip){
 if(xa>xb){let t=xa;xa=xb;xb=t;t=ya;ya=yb;yb=t;}
 const n=xb-xa;const out=[];
 if(n===0){out.push(box({at:[xa,Math.min(ya,yb),z],size:[1,Math.abs(yb-ya)+th,d],colour:c}));return out;}
 for(let i=0;i<=n;i++){
  const y1=ya+(yb-ya)*i/n;const y2=ya+(yb-ya)*Math.min(i+1,n)/n;
  const lo=Math.round(Math.min(y1,y2));const hi=Math.round(Math.max(y1,y2));
  out.push(box({at:[xa+i,lo,z],size:[1,hi-lo+th,d],colour:tip?tip(xa+i):c}));
 }
 return out;
}
function wheel(cx){
 const o=[];
 [[140,120,'black'],[120,100,'light bluish grey']].forEach(([ro,ri,c])=>{
  const rows=[];
  for(let r=0;r<35;r++){
   const dy=(r+0.5)*8-140;
   const oh=ro*ro>dy*dy?Math.round(Math.sqrt(ro*ro-dy*dy)/20):0;
   const ih=ri*ri>dy*dy?Math.round(Math.sqrt(ri*ri-dy*dy)/20):0;
   let segs=[];
   if(oh>0){if(ih===0)segs=[[cx-oh,2*oh]];else if(oh>ih)segs=[[cx-oh,oh-ih],[cx+ih,oh-ih]];}
   rows.push(JSON.stringify(segs));
  }
  let r=0;
  while(r<35){
   let n=1;while(r+n<35&&rows[r+n]===rows[r])n++;
   JSON.parse(rows[r]).forEach(([x,w])=>o.push(slab(x,r,1,w,n,2,c)));
   r+=n;
  }
 });
 o.push(box({at:[cx,5,1],size:[1,25,2],colour:'light bluish grey'}));
 o.push(slab(cx-5,17,1,10,1,2,'light bluish grey'));
 o.push(tube(cx-4,10,cx+4,24,1,2,3,'light bluish grey'));
 o.push(tube(cx-4,24,cx+4,10,1,2,3,'light bluish grey'));
 o.push(box({at:[cx-1,15,0],size:[3,5,4],colour:'dark bluish grey'}));
 return o;
}
