 box({at:[9,37,1],size:[4,3,2],colour:'white'}),
 box({at:[5,36,1],size:[4,3,2],colour:'dark bluish grey'}),
 box({at:[20,49,1],size:[3,8,2],colour:'white'}),
 box({at:[21,57,1],size:[3,6,2],colour:'white'}),
 box({at:[22,63,0],size:[5,8,4],colour:'white'}),
 place({part:'3005',at:[25,67,0],colour:'black'}),
 place({part:'3005',at:[25,67,3],colour:'black'}),
 box({at:[21,71,0],size:[6,3,4],colour:'blue'}),
 slab(22,74,1,4,2,2,'blue'),
 box({at:[27,67,1],size:[6,3,2],colour:'orange'}),
 box({at:[33,65,1],size:[6,3,2],colour:'orange'}),
 box({at:[27,61,1],size:[6,6,2],colour:'bright light orange'}),
 box({at:[28,59,1],size:[4,2,2],colour:'bright light orange'}),
 box({at:[33,62,1],size:[5,3,2],colour:'bright light orange'}),
 box({at:[38,62,1],size:[1,3,2],colour:'dark orange'}),
 tube(17,44,32,37,-1,1,6,'white',tip),
 tube(17,44,32,37,4,1,6,'white',tip),
 tube(17,31,25,13,0,1,3,'orange'),
 tube(17,31,19,8,3,1,3,'orange'),
 slab(24,11,0,4,2,1,'orange'),
 slab(17,6,3,4,2,1,'orange')
]);
